package ua.energykits.app;
import android.app.*; import android.os.*; import android.widget.*; import android.view.*; import android.graphics.Color; import android.content.*; import android.net.Uri; import org.json.*; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root, results; EditText inv,bat,ip,bp,iv,bv,ah,bms,watts; JSONArray kits=new JSONArray();
 EditText field(String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);root.addView(e);return e;}
 void button(String name,Runnable action){Button b=new Button(this);b.setText(name);root.addView(b);b.setOnClickListener(v->action.run());}
 double num(EditText e){double x=Double.parseDouble(e.getText().toString().replace(',','.'));if((Double.isNaN(x)||Double.isInfinite(x))||x<=0)throw new IllegalArgumentException();return x;}
 public void onCreate(Bundle b){super.onCreate(b);try{kits=new JSONArray(getPreferences(Context.MODE_PRIVATE).getString("kits","[]"));}catch(Exception ignored){}
 ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,48,24,32);root.setBackgroundColor(Color.rgb(12,32,60));s.addView(root);setContentView(s);
 TextView title=new TextView(this);title.setText("⚡ Підбір енергокомплектів");title.setTextSize(25);root.addView(title);
 inv=field("Модель інвертора",android.text.InputType.TYPE_CLASS_TEXT);ip=field("Ціна інвертора, грн",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);iv=field("Номінальна напруга системи, В",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);watts=field("Потужність інвертора, Вт",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
 button("Знайти інвертор в інтернеті",()->search(inv.getText().toString()+" інвертор ціна Україна"));
 bat=field("Модель акумулятора",android.text.InputType.TYPE_CLASS_TEXT);bp=field("Ціна АКБ, грн",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);bv=field("Номінальна напруга АКБ, В",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);ah=field("Ємність АКБ, А·год",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);bms=field("Тривалий струм BMS, А",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
 button("Знайти акумулятор в інтернеті",()->search(bat.getText().toString()+" LiFePO4 акумулятор ціна Україна"));
 button("Додати комплект",()->add());button("Новий вибір",()->{for(EditText e:new EditText[]{inv,bat,ip,bp,iv,bv,ah,bms,watts})e.setText("");});
 results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);render();}
 void search(String q){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(q))));}catch(Exception e){Toast.makeText(this,"Браузер недоступний",Toast.LENGTH_SHORT).show();}}
 void add(){try{double v=num(iv),a=num(bv),p=num(watts),current=num(bms);if(inv.getText().toString().trim().isEmpty()||bat.getText().toString().trim().isEmpty())throw new IllegalArgumentException();JSONObject k=new JSONObject();k.put("name",inv.getText()+" + "+bat.getText());k.put("price",num(ip)+num(bp));k.put("energy",a*num(ah)/1000);k.put("note",Math.abs(v-a)/v>0.1?"Напруга не відповідає":p>v*0.9*current*0.9?"BMS може обмежувати потужність":"Попередня оцінка струму достатня; перевірте паспорт і протоколи");kits.put(k);save();render();}catch(Exception e){Toast.makeText(this,"Заповніть усі поля коректними значеннями",Toast.LENGTH_SHORT).show();}}
 void save(){getPreferences(Context.MODE_PRIVATE).edit().putString("kits",kits.toString()).apply();}
 void render(){results.removeAllViews();ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<kits.length();i++)list.add(kits.optJSONObject(i));Collections.sort(list,(a,b)->Double.compare(a.optDouble("price"),b.optDouble("price")));for(JSONObject k:list){TextView t=new TextView(this);t.setText(k.optString("name")+"\n"+k.optDouble("price")+" грн | "+k.optDouble("energy")+" кВт·год\n"+k.optString("note")+"\nЦіна введена вручну");t.setTextSize(18);t.setPadding(12,18,12,18);results.addView(t);}}
}